mapper.select:
SELECT
    user_id, user_name, role_cd, plan_cd, tenant_id, register_date, register_user
FROM SES_AI_WEBAPP_M_USER
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE SES_AI_WEBAPP_M_USER
SET
    user_name = #{userName},
    role_cd = #{role, typeHandler=org.apache.ibatis.type.EnumTypeHandler},
    plan_cd = #{plan, typeHandler=org.apache.ibatis.type.EnumTypeHandler},
    register_date = #{registerDate, typeHandler=copel.sesproductpackage.core.database.typehandler.OriginalDateTimeTypeHandler},
    register_user = #{registerUser}
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM SES_AI_WEBAPP_M_USER
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
